    'ruleChomp': {
      'en': 'Pick a square: it and everything to its right and below vanish.\nThe top-left square is poison. Whoever eats it loses!',
      'ko': '초콜릿 한 칸을 고르면 그 칸의 오른쪽·아래가 전부 사라져요.\n왼쪽 위 칸은 독! 독을 먹는 사람이 져요.',
      'ja': '1マス選ぶと、その右と下が全部消えるよ。\n左上のマスは毒！毒を食べた人が負け。',
      'zh': '选一格，它右边和下边的全都消失。\n左上角那格是毒！吃到毒的人输。',
      'es': 'Elige una casilla: desaparece ella y todo lo de su derecha y abajo.\nLa de arriba a la izquierda es veneno. ¡Quien la coma, pierde!',
      'pt': 'Escolha um quadrado: ele e tudo à direita e abaixo somem.\nO do canto superior esquerdo é veneno. Quem comer, perde!',
      'de': 'Wähle ein Feld: es und alles rechts und darunter verschwindet.\nDas Feld oben links ist Gift. Wer es isst, verliert!',
      'fr': 'Choisis une case : elle disparaît avec tout ce qui est à droite et en dessous.\nLa case en haut à gauche est empoisonnée. Qui la mange perd !',
      'id': 'Pilih satu kotak: kotak itu dan semua di kanan serta bawahnya hilang.\nKotak kiri atas beracun. Yang memakannya kalah!',
      'vi': 'Chọn một ô: ô đó cùng mọi ô bên phải và bên dưới biến mất.\nÔ trên cùng bên trái có độc. Ai ăn nó thì thua!',
    },
    'ruleDots': {
      'en': 'Draw a line between two dots.\nComplete a box: it\'s yours, and you go again!\nMost boxes wins.',
      'ko': '점과 점 사이에 선을 그어요.\n네모를 완성하면 내 것 + 한 번 더!\n네모를 더 많이 먹은 사람이 이겨요.',
      'ja': '点と点の間に線を引くよ。\n四角を完成させたら自分のもの＋もう1回！\n四角が多い方の勝ち。',
      'zh': '在两点之间画线。\n完成一个格子就归你，还能再走一次！\n格子多的人赢。',
      'es': 'Traza una línea entre dos puntos.\nSi cierras una caja, es tuya y repites turno.\nGana quien tenga más cajas.',
      'pt': 'Trace uma linha entre dois pontos.\nFechou uma caixa? É sua, e joga de novo!\nQuem tiver mais caixas vence.',
      'de': 'Zieh eine Linie zwischen zwei Punkten.\nSchliesst du ein Kästchen, gehört es dir und du bist nochmal dran!\nWer mehr Kästchen hat, gewinnt.',
      'fr': 'Trace un trait entre deux points.\nTu fermes une case ? Elle est à toi et tu rejoues !\nLe plus de cases gagne.',
      'id': 'Tarik garis di antara dua titik.\nLengkapi kotak: jadi milikmu, dan jalan lagi!\nYang kotaknya paling banyak menang.',
      'vi': 'Vẽ một đoạn nối hai chấm.\nKhép kín một ô: ô đó là của bạn và được đi thêm!\nAi nhiều ô hơn thì thắng.',
    },
    'ruleSim': {
      'en': 'Six dots, fifteen lines. Take turns coloring a line.\nMake a triangle in your color and you lose!',
      'ko': '점 6개를 잇는 선 15개를 번갈아 내 색으로 칠해요.\n내 색으로 삼각형을 만들면 져요!',
      'ja': '点6つ、線15本。交互に線を自分の色で塗るよ。\n自分の色で三角形を作ったら負け！',
      'zh': '六个点，十五条线。轮流把线涂成自己的颜色。\n用自己的颜色围成三角形就输！',
      'es': 'Seis puntos, quince líneas. Por turnos, colorea una línea.\n¡Si formas un triángulo de tu color, pierdes!',
      'pt': 'Seis pontos, quinze linhas. Cada um colore uma linha por vez.\nFormou um triângulo da sua cor? Perdeu!',
      'de': 'Sechs Punkte, fünfzehn Linien. Abwechselnd färbst du eine Linie.\nBildest du ein Dreieck in deiner Farbe, verlierst du!',
      'fr': 'Six points, quinze traits. Chacun son tour colore un trait.\nUn triangle de ta couleur et tu perds !',
      'id': 'Enam titik, lima belas garis. Bergantian mewarnai satu garis.\nBentuk segitiga dengan warnamu, kamu kalah!',
      'vi': 'Sáu điểm, mười lăm đoạn. Lần lượt tô một đoạn theo màu của mình.\nTạo thành tam giác cùng màu là thua!',
    },
    'ruleSprouts': {
      'en': 'Connect two dots with a straight line; a new dot sprouts in the middle.\nLines can\'t cross. Each dot takes at most 3 lines.\nCan\'t move? You lose.',
      'ko': '점 두 개를 직선으로 잇고, 그 한가운데에 새 점이 생겨요.\n선은 서로 못 넘고, 한 점에 선은 3개까지.\n더 이을 수 없는 사람이 져요.',
      'ja': '2つの点を直線でつなぐと、真ん中に新しい点が生えるよ。\n線は交差できない。1つの点に線は3本まで。\nつなげなくなった人が負け。',
      'zh': '用直线连接两个点，中间会长出一个新点。\n线不能交叉，每个点最多连3条线。\n没法再连的人输。',
      'es': 'Une dos puntos con una recta; en el medio brota un punto nuevo.\nLas líneas no se cruzan. Cada punto admite 3 líneas como máximo.\nSi no puedes mover, pierdes.',
      'pt': 'Ligue dois pontos com uma reta; no meio nasce um ponto novo.\nAs linhas não se cruzam. Cada ponto aceita no máximo 3 linhas.\nQuem não puder jogar, perde.',
      'de': 'Verbinde zwei Punkte mit einer Geraden; in der Mitte spriesst ein neuer Punkt.\nLinien dürfen sich nicht kreuzen. Höchstens 3 Linien pro Punkt.\nWer nicht mehr ziehen kann, verliert.',
      'fr': 'Relie deux points par un trait droit ; un nouveau point pousse au milieu.\nLes traits ne se croisent pas. 3 traits max par point.\nPlus de coup possible ? Tu perds.',
      'id': 'Hubungkan dua titik dengan garis lurus; titik baru tumbuh di tengahnya.\nGaris tidak boleh bersilang. Tiap titik maksimal 3 garis.\nTidak bisa jalan? Kamu kalah.',
      'vi': 'Nối hai điểm bằng một đoạn thẳng; một điểm mới mọc ở giữa.\nCác đoạn không được cắt nhau. Mỗi điểm tối đa 3 đoạn.\nHết nước đi là thua.',
    },
    'ruleHex': {
      'en': 'Take turns filling one cell.\nYou win by linking LEFT to RIGHT. Yerin links TOP to BOTTOM.\nThere are no draws.',
      'ko': '번갈아 한 칸씩 칠해요.\n나는 왼쪽↔오른쪽, 예린은 위↔아래를 이으면 승리!\n무승부는 없어요.',
      'ja': '交互に1マスずつ塗るよ。\n君は左↔右、イェリンは上↔下をつなげば勝ち！\n引き分けはない。',
      'zh': '轮流涂一格。\n你连通左↔右就赢，艺琳连通上↔下。\n没有平局。',
      'es': 'Por turnos, colorea una celda.\nTú ganas uniendo IZQUIERDA y DERECHA. Yerin une ARRIBA y ABAJO.\nNo hay empates.',
      'pt': 'Cada um pinta uma célula por vez.\nVocê vence ligando ESQUERDA e DIREITA. A Yerin liga CIMA e BAIXO.\nNão existe empate.',
      'de': 'Abwechselnd färbst du ein Feld.\nDu gewinnst, wenn du LINKS mit RECHTS verbindest. Yerin verbindet OBEN mit UNTEN.\nEs gibt kein Unentschieden.',
      'fr': 'Chacun son tour colore une case.\nTu gagnes en reliant GAUCHE et DROITE. Yerin relie HAUT et BAS.\nPas de match nul.',
      'id': 'Bergantian mewarnai satu sel.\nKamu menang jika menghubungkan KIRI dan KANAN. Yerin menghubungkan ATAS dan BAWAH.\nTidak ada seri.',
      'vi': 'Lần lượt tô một ô.\nBạn thắng khi nối TRÁI với PHẢI. Yerin nối TRÊN với DƯỚI.\nKhông có hòa.',
