    'sc_w1_4_7': {
      'en': 'When I walked alone, the candy never ran out this fast.',
      'ko': '혼자 걸을 땐 사탕이 이렇게 빨리 안 줄었거든.',
      'ja': '一人で歩いてた時は、飴がこんなに早く減らなかったから。',
      'zh': '一个人走的时候,糖果没有这么快就没了。',
