      'vi': 'Xin lỗi vì chuyện đó.',
    },
    'sc_w1_4_9': {
      'en': 'Don\'t apologize. It\'s not a bad thing that it\'s running out.',
      'ko': '사과하지 마. 줄어드는 게 나쁜 건 아니니까.',
      'ja': '謝らないで。減るのが悪いわけじゃないから。',
