    'sc_w2_1_4': {
      'en': 'I liked how the wind felt like it was telling me the answer.',
      'ko': '바람이 답을 알려주는 느낌이라 좋아했어.',
      'ja': '風が答えを教えてくれるみたいな感じが好きだった。',
