      'vi': 'Lộ vậy sao?',
    },
    'sc_w2_3_6': {
      'en': 'It does. Not a bad thing though. It\'s the face of someone trying to win.',
      'ko': '나. 나쁘진 않아. 이기려고 하는 얼굴이라.',
      'ja': '見えるよ。悪くはない。勝とうとしてる顔だから。',
      'zh': '看得出来。不算难看。那是想赢的表情。',
      'es': 'Sí. No está mal. Es la cara de alguien que intenta ganar.',
