    'sc_w2_4_title': {
      'en': 'Rooftop Wind',
      'ko': '옥상의 바람',
      'ja': '屋上の風',
      'zh': '天台的风',
      'es': 'El viento de la azotea',
      'pt': 'O vento do telhado',
      'de': 'Der Wind auf dem Dach',
      'fr': 'Le vent du toit',
      'id': 'Angin di atap',
      'vi': 'Gió trên sân thượng',
    },
    'sc_w2_4_1': {
      'en': 'Two rows, done too. You won on a windless day, so I\'ll admit it.',
      'ko': '두 줄도 끝. 바람 없는 날에 이겼으니까 인정.',
      'ja': '二列も終わり。無風の日に勝ったんだから認める。',
      'zh': '两行也结束了。在没有风的日子赢的,我认。',
      'es': 'Dos filas, terminado también. Ganaste en un día sin viento, así que lo reconozco.',
      'pt': 'Duas fileiras, terminado também. Você ganhou num dia sem vento, então eu reconheço.',
      'de': 'Zwei Reihen, auch geschafft. Du hast an einem windstillen Tag gewonnen, das erkenn ich an.',
      'fr': 'Deux rangées, terminé aussi. T\'as gagné un jour sans vent, alors je l\'admets.',
      'id': 'Dua baris juga selesai. Kamu menang di hari tanpa angin, jadi kuakui.',
      'vi': 'Hai hàng cũng xong luôn. Cậu thắng vào ngày không có gió, nên tôi công nhận.',
    },
    'sc_w2_4_2': {
      'en': 'The librarian teacher said I\'ve been smiling more lately.',
      'ko': '사서 선생님이 그러더라. 요즘 웃는 얼굴이 늘었다고.',
      'ja': '司書の先生が言ってた。最近笑顔が増えたって。',
      'zh': '图书管理老师说,我最近笑容变多了。',
      'es': 'La bibliotecaria me dijo que últimamente sonrío más.',
      'pt': 'A bibliotecária disse que ultimamente eu tenho sorrido mais.',
      'de': 'Die Bibliothekslehrerin meinte, ich würde in letzter Zeit öfter lächeln.',
      'fr': 'La bibliothécaire m\'a dit que je souriais plus ces derniers temps.',
      'id': 'Guru pustakawan bilang, akhir-akhir ini aku lebih sering tersenyum.',
      'vi': 'Cô thủ thư nói dạo này tôi cười nhiều hơn.',
    },
    'sc_w2_4_3': {
      'en': 'Why?',
      'ko': '왜?',
      'ja': 'なんで?',
      'zh': '为什么?',
      'es': '¿Por qué?',
      'pt': 'Por quê?',
      'de': 'Warum?',
      'fr': 'Pourquoi ?',
      'id': 'Kenapa?',
      'vi': 'Tại sao?',
    },
    'sc_w2_4_4': {
      'en': '…It\'s because of the rooftop wind.',
      'ko': '…옥상 바람 때문이야.',
      'ja': '…屋上の風のせいだよ。',
      'zh': '……是因为天台的风啦。',
      'es': '...Es por el viento de la azotea.',
      'pt': '...É por causa do vento do telhado.',
      'de': '…Wegen dem Wind auf dem Dach.',
      'fr': '...C\'est à cause du vent du toit.',
      'id': '...Itu karena angin di atap.',
      'vi': '...Là tại gió trên sân thượng thôi.',
    },
    'sc_w2_4_5': {
      'en': 'There was no wind that day though.',
      'ko': '바람 없는 날이었는데.',
      'ja': '無風の日だったけど。',
      'zh': '那天明明没有风。',
      'es': 'Pero ese día no había viento.',
      'pt': 'Mas naquele dia não tinha vento.',
      'de': 'Aber da war doch gar kein Wind.',
      'fr': 'Mais y avait pas de vent ce jour-là.',
      'id': 'Padahal waktu itu hari tanpa angin.',
      'vi': 'Nhưng hôm đó đâu có gió.',
    },
    'sc_w2_4_6': {
      'en': 'You\'re not supposed to point that out.',
      'ko': '그런 건 따지는 거 아니야.',
      'ja': 'そういうのは突っ込まないの。',
      'zh': '这种事就别追究了。',
      'es': 'Eso no se cuestiona.',
      'pt': 'Isso não se questiona.',
      'de': 'Sowas hinterfragt man nicht.',
      'fr': 'On ne relève pas ce genre de truc.',
      'id': 'Hal seperti itu jangan dipermasalahkan.',
      'vi': 'Chuyện đó đừng có bắt bẻ.',
    },
    'sc_w2_4_7': {
      'en': 'I\'m staying in the classroom after school. I\'ve got a club that bakes cookies.',
      'ko': '방과후에 교실에 남을 거야. 쿠키 굽는 부활동이 있거든.',
      'ja': '放課後、教室に残るの。クッキーを焼く部活があるから。',
      'zh': '放学后我要留在教室。有个烤饼干的社团活动。',
      'es': 'Me voy a quedar en el aula después de clase. Tengo un club de repostería de galletas.',
      'pt': 'Vou ficar na sala depois da aula. Tenho um clube que faz biscoitos.',
      'de': 'Ich bleib nach der Schule im Klassenzimmer. Ich hab einen Club, in dem wir Kekse backen.',
      'fr': 'Je reste en classe après les cours. J\'ai un club où on fait des cookies.',
      'id': 'Aku akan tinggal di kelas setelah pulang sekolah. Ada kegiatan klub membuat kukis.',
      'vi': 'Sau giờ học tôi sẽ ở lại lớp. Có câu lạc bộ làm bánh quy đấy.',
    },
    'sc_w2_4_8': {
      'en': 'Can I stay too?',
      'ko': '나도 남아도 돼?',
      'ja': '俺も残っていい?',
      'zh': '我也可以留下吗?',
      'es': '¿Puedo quedarme yo también?',
      'pt': 'Posso ficar também?',
      'de': 'Darf ich auch bleiben?',
