      'id': 'Aku boleh ikut tinggal juga?',
      'vi': 'Tôi cũng ở lại được không?',
    },
    'sc_w2_4_9': {
      'en': 'Three rows is a bit hard. Come if you\'re prepared.',
      'ko': '세 줄은 좀 어려워. 각오하고 오면.',
      'ja': '三列はちょっと難しいよ。覚悟して来るなら。',
      'zh': '三行有点难哦。做好心理准备再来吧。',
      'es': 'Tres filas es un poco difícil. Ven si estás preparado.',
