      'ko': '각오했어.',
      'ja': '覚悟してる。',
      'zh': '我准备好了。',
      'es': 'Estoy preparado.',
      'pt': 'Estou preparado.',
      'de': 'Bin bereit.',
      'fr': 'Je suis prêt.',
      'id': 'Aku sudah siap.',
      'vi': 'Tôi chuẩn bị rồi.',
    },
    'sc_w2_4_11': {
      'en': 'Then it\'s settled. Don\'t spill crumbs. It\'s my desk.',
      'ko': '그럼 됐어. 부스러기는 흘리지 마. 내 책상이니까.',
