    'sc_w3_4_1': {
      'en': 'You\'ve cleared up to three rows. The Nim game is yours now.',
      'ko': '세 줄까지 다 깼어. 님게임은 이제 네 거야.',
      'ja': '三列まで全部クリアした。ニムゲームはもうあんたのものだよ。',
      'zh': '三行也都通关了。尼姆游戏现在是你的了。',
      'es': 'Superaste hasta las tres filas. El juego de Nim ya es tuyo.',
      'pt': 'Você zerou até três fileiras. O jogo de Nim agora é seu.',
      'de': 'Bis zu drei Reihen hast du alles geschafft. Das Nim-Spiel gehört jetzt dir.',
      'fr': 'T\'as fini jusqu\'à trois rangées. Le jeu de Nim, c\'est le tien maintenant.',
      'id': 'Sampai tiga baris pun sudah kamu tamatkan. Permainan Nim sekarang milikmu.',
      'vi': 'Ba hàng cũng phá đảo hết rồi. Trò Nim giờ là của cậu đấy.',
    },
    'sc_w3_4_2': {
      'en': 'At first I thought you\'d quit soon. Everyone else did.',
      'ko': '처음엔 금방 그만둘 줄 알았어. 다들 그랬으니까.',
      'ja': '最初はすぐやめると思ってた。みんなそうだったから。',
      'zh': '一开始以为你很快就会放弃。因为大家都是这样。',
      'es': 'Al principio pensé que lo dejarías pronto. Todos lo hicieron.',
      'pt': 'No começo achei que você desistiria logo. Todo mundo desistiu.',
      'de': 'Am Anfang dachte ich, du hörst schnell wieder auf. Alle anderen haben das getan.',
      'fr': 'Au début je pensais que t\'abandonnerais vite. Tout le monde l\'a fait.',
      'id': 'Awalnya kukira kamu akan cepat berhenti. Soalnya semua orang begitu.',
      'vi': 'Lúc đầu tôi nghĩ cậu sẽ bỏ cuộc sớm. Vì ai cũng vậy cả.',
    },
    'sc_w3_4_3': {
      'en': 'Everyone?',
      'ko': '다들?',
      'ja': 'みんな?',
      'zh': '大家?',
      'es': '¿Todos?',
      'pt': 'Todo mundo?',
      'de': 'Alle?',
      'fr': 'Tout le monde ?',
      'id': 'Semua orang?',
      'vi': 'Ai cũng vậy?',
    },
    'sc_w3_4_4': {
      'en': 'Once I explained the rules, they\'d say it\'s no fun and leave. But you came every day. Even on days you lost.',
      'ko': '규칙 알려주면 재미없다고 가더라. 근데 넌 매일 왔어. 지는 날에도.',
      'ja': 'ルールを教えたら、つまらないって行っちゃうの。でもあんたは毎日来た。負ける日にも。',
      'zh': '告诉规则后,他们都说没意思就走了。可你每天都来。输的日子也是。',
      'es': 'Cuando les explicaba las reglas, decían que no era divertido y se iban. Pero tú venías todos los días. Incluso cuando perdías.',
      'pt': 'Quando eu explicava as regras, eles diziam que não tinha graça e iam embora. Mas você vinha todo dia. Até nos dias em que perdia.',
      'de': 'Wenn ich die Regeln erklärt hab, sind alle gegangen, weil\'s ihnen langweilig war. Aber du bist jeden Tag gekommen. Auch an Tagen, an denen du verloren hast.',
      'fr': 'Une fois les règles expliquées, ils disaient que c\'était pas marrant et partaient. Mais toi, tu venais tous les jours. Même les jours où tu perdais.',
      'id': 'Begitu tahu aturannya, mereka bilang tidak seru lalu pergi. Tapi kamu datang setiap hari. Bahkan di hari-hari saat kalah.',
      'vi': 'Hễ biết luật là họ bảo chán rồi bỏ đi. Nhưng cậu thì ngày nào cũng đến. Cả những ngày thua cũng vậy.',
    },
    'sc_w3_4_5': {
      'en': 'There were more days I lost.',
      'ko': '지는 날이 더 많았지.',
      'ja': '負ける日の方が多かったよ。',
      'zh': '输的日子更多呢。',
      'es': 'Hubo más días de derrota, la verdad.',
      'pt': 'Teve mais dias que eu perdi, na verdade.',
      'de': 'Es gab eher mehr Tage, an denen ich verloren hab.',
      'fr': 'Y avait plus de jours où je perdais, en fait.',
      'id': 'Hari-hari aku kalah malah lebih banyak.',
      'vi': 'Ngày thua còn nhiều hơn ấy chứ.',
    },
    'sc_w3_4_6': {
      'en': 'You know what that is? It\'s the thing I\'m worst at. Losing and coming back anyway.',
      'ko': '그게 뭔지 알아? 내가 제일 못 하는 거야. 지고 다시 오는 거.',
      'ja': 'それが何か分かる?私が一番苦手なことだよ。負けてまた来ること。',
      'zh': '你知道那是什么吗?那是我最不擅长的事。输了还继续来。',
      'es': '¿Sabes qué es eso? Es lo que peor se me da a mí. Perder y volver de todos modos.',
      'pt': 'Sabe o que é isso? É a coisa que eu sou pior fazendo. Perder e voltar de novo.',
      'de': 'Weißt du, was das ist? Das, worin ich am schlechtesten bin. Verlieren und trotzdem wiederkommen.',
      'fr': 'Tu sais ce que c\'est, ça ? C\'est ce que je fais le plus mal. Perdre et revenir quand même.',
      'id': 'Kamu tahu itu apa? Itu hal yang paling tidak bisa kulakukan. Kalah lalu tetap datang lagi.',
      'vi': 'Cậu biết đó là gì không? Đó là thứ tôi kém nhất. Thua rồi vẫn quay lại.',
    },
    'sc_w3_4_7': {
      'en': 'I borrowed the library key. For the night. The stick-candy game needs to be played somewhere quiet.',
      'ko': '도서관 열쇠 빌렸어. 밤에. 막대과자 게임은 조용한 데서 해야 하거든.',
      'ja': '図書館の鍵、借りたの。夜に。棒菓子ゲームは静かな場所でやらないとだから。',
      'zh': '我借了图书馆的钥匙。晚上用。棒状点心游戏得在安静的地方玩才行。',
      'es': 'Pedí prestada la llave de la biblioteca. Para la noche. El juego de los palitos de caramelo hay que jugarlo en un lugar tranquilo.',
      'pt': 'Peguei emprestada a chave da biblioteca. Pra noite. O jogo dos palitinhos precisa ser jogado num lugar quieto.',
      'de': 'Ich hab mir den Bibliotheksschlüssel geliehen. Für abends. Das Stäbchen-Spiel muss man an einem ruhigen Ort spielen.',
      'fr': 'J\'ai emprunté la clé de la bibliothèque. Pour le soir. Le jeu des bâtonnets, faut y jouer dans un endroit calme.',
      'id': 'Aku pinjam kunci perpustakaan. Untuk malam hari. Permainan stik permen harus dimainkan di tempat yang tenang.',
      'vi': 'Tôi mượn chìa khóa thư viện rồi. Cho buổi tối. Trò chơi que kẹo phải chơi ở chỗ yên tĩnh mới được.',
    },
    'sc_w3_4_8': {
      'en': 'At night?',
      'ko': '밤에?',
      'ja': '夜に?',
      'zh': '晚上?',
      'es': '¿De noche?',
      'pt': 'De noite?',
      'de': 'Abends?',
      'fr': 'Le soir ?',
      'id': 'Malam hari?',
      'vi': 'Buổi tối à?',
    },
    'sc_w3_4_9': {
      'en': 'The librarian teacher gave permission. Said it\'s fine if it\'s the two of us.',
      'ko': '사서 선생님이 허락했어. 둘이면 괜찮대.',
      'ja': '司書の先生が許可してくれた。二人ならいいって。',
      'zh': '图书管理老师同意了。说两个人的话没问题。',
      'es': 'La bibliotecaria dio permiso. Dijo que estaba bien si somos los dos.',
      'pt': 'A bibliotecária deu permissão. Disse que tá bom se formos nós dois.',
      'de': 'Die Bibliothekslehrerin hat\'s erlaubt. Meinte, zu zweit sei es okay.',
      'fr': 'La bibliothécaire a donné son accord. Elle a dit que ça allait si on est deux.',
      'id': 'Guru pustakawan sudah mengizinkan. Katanya tidak apa-apa kalau berdua.',
      'vi': 'Cô thủ thư đã cho phép rồi. Bảo là hai người thì được.',
    },
    'sc_w3_4_10': {
