      'ko': '같이 가자는 거야?',
      'ja': '一緒に行こうってこと?',
      'zh': '是叫我一起去吗?',
      'es': '¿Me estás pidiendo que vayamos juntos?',
      'pt': 'Está me chamando pra irmos juntos?',
