      'id': 'Maksudnya ajak aku pergi bersama?',
      'vi': 'Ý cậu là rủ tôi đi cùng à?',
    },
    'sc_w3_4_11': {
      'en': '…I won\'t say it twice.',
      'ko': '…두 번 말 안 해.',
      'ja': '…二度は言わないから。',
      'zh': '……我不会说第二遍的。',
      'es': '...No lo voy a repetir.',
