      'ko': '혼자 쪼개 보면서. 여기서. 밤에.',
      'ja': '一人で分けてみながら。ここで。夜に。',
      'zh': '自己一个人试着分。就在这里。晚上。',
      'es': 'Partiéndolos yo sola. Aquí. De noche.',
