    'sc_w4_2_4': {
      'en': 'You did it in ten rounds. …I decided not to be surprised anymore.',
      'ko': '너는 열 판. …이제 안 놀라기로 했어.',
      'ja': 'あんたは十回。…もう驚かないことにした。',
      'zh': '你十局就会了。…我决定以后不再惊讶了。',
      'es': 'Tú en diez partidas. …Decidí no sorprenderme más.',
      'pt': 'Você aprendeu em dez partidas. …Decidi não me surpreender mais.',
      'de': 'Du in zehn Runden. …Ich hab beschlossen, mich nicht mehr zu wundern.',
      'fr': 'Toi, en dix parties. …J\'ai décidé de ne plus être surprise.',
      'id': 'Kamu cuma sepuluh ronde. …Aku memutuskan untuk berhenti terkejut.',
