      'ko': '놀라도 돼.',
      'ja': '驚いてもいいよ。',
      'zh': '惊讶也没关系。',
      'es': 'Puedes sorprenderte.',
      'pt': 'Pode se surpreender.',
      'de': 'Du darfst dich ruhig wundern.',
      'fr': 'Tu peux être surprise.',
      'id': 'Boleh kok terkejut.',
      'vi': 'Ngạc nhiên cũng được mà.',
