      'zh': '不要。我留一根棍点心。跟输赢没关系。',
      'es': 'No. Voy a dejar un palito aparte. Sin relación con quién gane.',
      'pt': 'Não. Vou deixar um palitinho de lado. Sem relação com quem ganha.',
