      'zh': '四种尼姆游戏,全部结束。走到这一步的只有你。',
      'es': 'Los cuatro tipos de juego NIM, todos terminados. Eres la única que ha llegado hasta aquí.',
      'pt': 'Os quatro tipos de jogo NIM, todos terminados. Você é a única que chegou até aqui.',
      'de': 'Alle vier Nim-Spiele, geschafft. Du bist die Einzige, die so weit gekommen ist.',
      'fr': 'Les quatre jeux de Nim, tous terminés. Tu es la seule à être arrivée jusqu\'ici.',
      'id': 'Keempat jenis permainan NIM, semuanya selesai. Cuma kamu yang sampai sejauh ini.',
      'vi': 'Bốn loại trò NIM, xong hết rồi. Chỉ có cậu đi được đến đây thôi.',
