    'sc_w4_4_2': {
      'en': 'Look at this notebook. I wrote it while playing alone.',
      'ko': '이 노트 봐. 내가 혼자 두면서 적어둔 거야.',
      'ja': 'このノート見て。私が一人で打ちながら書いたやつ。',
      'zh': '看这本笔记。是我一个人下棋时写的。',
      'es': 'Mira este cuaderno. Lo escribí jugando sola.',
      'pt': 'Olha esse caderno. Escrevi jogando sozinha.',
      'de': 'Schau dir dieses Notizbuch an. Ich hab\'s geschrieben, während ich allein gespielt hab.',
      'fr': 'Regarde ce carnet. Je l\'ai écrit en jouant seule.',
      'id': 'Lihat buku catatan ini. Aku tulis sambil main sendirian.',
      'vi': 'Nhìn cuốn sổ này xem. Tớ viết trong lúc tự chơi một mình đấy.',
