      'vi': 'Cho tớ xem được không?',
    },
    'sc_w4_4_4': {
      'en': 'What you figured out on your own matched what\'s written here. That\'s why.',
      'ko': '네가 스스로 찾아낸 게 여기 적힌 거랑 똑같더라. 그래서.',
      'ja': 'あんたが自分で見つけたのが、ここに書いてあるのと同じだった。だから。',
