    'sc_w6_2_3': {
      'en': 'Yes. There\'s a spot where the two piles line up perfectly.',
      'ko': '응. 두 무더기가 예쁘게 맞는 자리가 있어.',
      'ja': 'うん。二つの山がぴったり合う位置があるの。',
      'zh': '嗯。有一个两堆完美对应的位置。',
