    'sc_w6_2_5': {
      'en': 'That\'s pretty.',
      'ko': '예쁘네.',
      'ja': 'きれいだね。',
      'zh': '挺漂亮的。',
      'es': 'Qué bonito.',
      'pt': 'Que bonito.',
      'de': 'Schön.',
      'fr': 'C\'est joli.',
      'id': 'Indah ya.',
      'vi': 'Đẹp thật.',
    },
    'sc_w6_2_6': {
      'en': '…Your moves are sometimes just as pretty. Mathematically.',
      'ko': '…네가 두는 수도 가끔 그렇게 예뻐. 수학적으로.',
      'ja': '…あんたの打つ手も時々そんな風にきれい。数学的に。',
      'zh': '…你落的那些数字有时候也那么漂亮。数学意义上的。',
      'es': 'A veces tus jugadas también son así de bonitas. Matemáticamente.',
