    'sc_w6_3_1': {
      'en': 'Like the hole in a donut, is there a gap in your logic…',
      'ko': '도넛 구멍처럼 네 논리엔 빈틈이…',
      'ja': 'ドーナツの穴みたいに、あんたの論理にも隙間が…',
      'zh': '就像甜甜圈中间的洞,你的逻辑里是不是也有破绽…',
