    },
    'sc_w6_3_6': {
      'en': 'Yeah. I like finding gaps. Yours especially.',
      'ko': '응. 빈틈 찾는 거 좋아해. 네 거는 특히.',
      'ja': 'うん。隙間見つけるの好き。あんたのは特に。',
      'zh': '嗯。我喜欢找破绽。尤其是你的。',
