    'sc_w6_4_title': {
      'en': 'Numbers in the Science Lab',
      'ko': '과학실의 숫자',
      'ja': '理科室の数字',
      'zh': '科学教室的数字',
      'es': 'Números en el laboratorio de ciencias',
      'pt': 'Números no laboratório de ciências',
      'de': 'Zahlen im Wissenschaftsraum',
      'fr': 'Les nombres dans le labo',
      'id': 'Angka di Ruang Sains',
      'vi': 'Những con số trong phòng khoa học',
    },
    'sc_w6_4_1': {
      'en': 'Cleared Wythoff\'s, too. You\'ve learned the golden ratio by hand.',
      'ko': '위토프까지 다 깼어. 황금비를 손으로 익힌 거야.',
      'ja': 'ウィトフまで全部クリアした。黄金比を手で覚えたってことだね。',
      'zh': '维索夫也全部通关了。等于是用手学会了黄金比。',
      'es': 'También terminé el de Wythoff. Aprendiste la proporción áurea con las manos.',
      'pt': 'Terminei o de Wythoff também. Você aprendeu a razão áurea na prática.',
      'de': 'Wythoff auch geschafft. Du hast den Goldenen Schnitt mit den Händen gelernt.',
      'fr': 'Wythoff aussi, terminé. Tu as appris le nombre d\'or avec tes mains.',
      'id': 'Wythoff juga sudah kutaklukkan. Kamu jadi paham rasio emas lewat tanganmu sendiri.',
      'vi': 'Cả Wythoff cũng phá đảo rồi. Coi như đã học tỷ lệ vàng bằng chính tay mình.',
    },
    'sc_w6_4_2': {
      'en': 'Numbers were always easier for me than people. Numbers don\'t betray you.',
      'ko': '나는 숫자가 사람보다 편했어. 숫자는 배신 안 하니까.',
      'ja': '私は人より数字の方が楽だった。数字は裏切らないから。',
      'zh': '比起人,我觉得数字更让我安心。因为数字不会背叛。',
      'es': 'Para mí, los números siempre fueron más fáciles que las personas. Los números no traicionan.',
      'pt': 'Pra mim, números sempre foram mais fáceis que pessoas. Números não traem.',
      'de': 'Zahlen waren mir immer leichter als Menschen. Zahlen verraten einen nicht.',
      'fr': 'Les nombres m\'ont toujours été plus faciles que les gens. Les nombres ne trahissent pas.',
      'id': 'Bagiku, angka selalu lebih mudah daripada orang. Angka nggak berkhianat.',
      'vi': 'Với tớ, số dễ chịu hơn người. Vì số không phản bội.',
    },
    'sc_w6_4_3': {
      'en': 'Do people betray you?',
      'ko': '사람은 배신해?',
      'ja': '人は裏切るの?',
      'zh': '人会背叛吗?',
      'es': '¿Las personas traicionan?',
      'pt': 'Pessoas traem?',
      'de': 'Verraten Menschen dich?',
      'fr': 'Les gens trahissent ?',
      'id': 'Orang berkhianat?',
      'vi': 'Người phản bội à?',
    },
    'sc_w6_4_4': {
      'en': 'Once I taught them the rules, everyone left. That\'s not really betrayal, though.',
      'ko': '규칙 알려주면 다들 갔어. 그게 배신은 아니지만.',
      'ja': 'ルール教えたらみんな去っていった。それは裏切りじゃないけど。',
      'zh': '教会规则之后大家都走了。虽然那不算背叛。',
      'es': 'Cada vez que enseñaba las reglas, todos se iban. Aunque eso no es traición, en realidad.',
      'pt': 'Toda vez que eu ensinava as regras, todo mundo ia embora. Isso não é bem traição, mas.',
      'de': 'Sobald ich die Regeln erklärt hab, sind alle gegangen. Das ist aber kein richtiger Verrat.',
      'fr': 'Chaque fois que j\'expliquais les règles, tout le monde partait. Ce n\'est pas vraiment une trahison, remarque.',
      'id': 'Setiap kali kuajari aturannya, semua orang pergi. Meskipun itu bukan benar-benar pengkhianatan.',
      'vi': 'Hễ dạy luật xong là ai cũng bỏ đi. Dù đó không hẳn là phản bội.',
    },
    'sc_w6_4_5': {
      'en': 'I never left.',
      'ko': '나는 안 갔잖아.',
      'ja': '私は去らなかったじゃん。',
      'zh': '我没走啊。',
      'es': 'Yo nunca me fui.',
      'pt': 'Eu não fui embora.',
      'de': 'Ich bin nicht gegangen.',
      'fr': 'Moi, je ne suis pas partie.',
      'id': 'Aku nggak pergi, kan.',
      'vi': 'Tớ có bỏ đi đâu.',
    },
    'sc_w6_4_6': {
      'en': '…No. You play differently every time, but you always end up in the right spot.',
      'ko': '…응. 너는 매번 다르게 두면서도 결국 맞는 자리로 와.',
      'ja': '…うん。あんたは毎回違う打ち方するのに、結局正しい場所に来る。',
      'zh': '…嗯。你每次下的都不一样,但最后总能走到对的位置。',
      'es': '…No. Tú juegas distinto cada vez, pero siempre terminas en el lugar correcto.',
      'pt': '…É. Você joga diferente toda vez, mas sempre acaba chegando no lugar certo.',
