    'sc_w7_2_1': {
      'en': 'I named the rabbits. One\'s Nim, the other\'s Game.',
      'ko': '토끼 이름 지었어. 하나는 님, 하나는 게임.',
      'ja': '名前決めた。一匹はニム、一匹はゲーム。',
      'zh': '我给兔子取名字了。一只叫尼姆,一只叫游戏。',
      'es': 'Les puse nombre a los conejos. Uno es Nim, el otro es Game.',
      'pt': 'Dei nome aos coelhos. Um é Nim, o outro é Game.',
      'de': 'Ich hab den Kaninchen Namen gegeben. Eins heißt Nim, eins heißt Game.',
      'fr': 'J\'ai donné des noms aux lapins. L\'un s\'appelle Nim, l\'autre Game.',
      'id': 'Aku sudah kasih nama kelincinya. Satu Nim, satu lagi Game.',
      'vi': 'Tớ đặt tên cho thỏ rồi. Một con là Nim, một con là Game.',
    },
    'sc_w7_2_2': {
      'en': '...Can I laugh?',
      'ko': '…웃어도 돼?',
      'ja': '…笑っていい?',
      'zh': '……我能笑吗?',
      'es': '...¿Puedo reírme?',
      'pt': '...Posso rir?',
      'de': '...Darf ich lachen?',
      'fr': '...Je peux rire ?',
      'id': '...Boleh aku ketawa?',
      'vi': '...Tớ cười được không?',
    },
    'sc_w7_2_3': {
      'en': 'No. I named them seriously.',
      'ko': '안 돼. 진지하게 지은 거야.',
      'ja': 'ダメ。真剣に考えたんだから。',
      'zh': '不行。我是认真取的。',
      'es': 'No. Se los puse en serio.',
      'pt': 'Não. Eu pensei sério nisso.',
      'de': 'Nein. Ich hab mir das ernsthaft überlegt.',
      'fr': 'Non. Je les ai choisis sérieusement.',
      'id': 'Nggak boleh. Aku serius waktu kasih nama itu.',
      'vi': 'Không được. Tớ đặt nghiêm túc đấy.',
    },
    'sc_w7_2_4': {
      'en': 'Fibonacci numbers apparently came from counting rabbits. So.',
      'ko': '피보나치 수는 토끼 세는 데서 나왔대. 그래서.',
      'ja': 'フィボナッチ数はウサギを数えるところから生まれたんだって。だから。',
      'zh': '听说斐波那契数就是从数兔子来的。所以。',
      'es': 'Dicen que los números de Fibonacci vienen de contar conejos. Por eso.',
      'pt': 'Dizem que os números de Fibonacci vieram de contar coelhos. Por isso.',
      'de': 'Die Fibonacci-Zahlen sollen vom Kaninchenzählen kommen. Deswegen.',
      'fr': 'Il paraît que les nombres de Fibonacci viennent du comptage des lapins. Voilà pourquoi.',
      'id': 'Katanya bilangan Fibonacci berasal dari hitung-hitungan kelinci. Makanya.',
      'vi': 'Nghe nói dãy Fibonacci bắt nguồn từ việc đếm thỏ. Nên là vậy.',
    },
    'sc_w7_2_5': {
      'en': 'Then what about the third rabbit?',
      'ko': '그럼 세 번째 토끼는?',
      'ja': 'じゃあ三匹目のウサギは?',
      'zh': '那第三只兔子呢?',
      'es': '¿Y el tercer conejo entonces?',
      'pt': 'E o terceiro coelho, então?',
      'de': 'Und was ist mit dem dritten Kaninchen?',
      'fr': 'Et le troisième lapin, alors ?',
      'id': 'Terus kelinci yang ketiga gimana?',
      'vi': 'Vậy con thỏ thứ ba thì sao?',
    },
    'sc_w7_2_6': {
      'en': 'It doesn\'t have a name yet. You name it — if you\'re still going to be here next year.',
      'ko': '아직 이름 없어. 네가 지어. 내년에도 여기 있을 거면.',
      'ja': 'まだ名前ない。あんたが決めて。来年もここにいるなら。',
      'zh': '还没取名字。你来取吧。如果明年你还在的话。',
      'es': 'Todavía no tiene nombre. Ponle uno tú. Si es que vas a seguir aquí el año que viene.',
      'pt': 'Ainda não tem nome. Bota você. Se é que você vai continuar aqui ano que vem.',
      'de': 'Der hat noch keinen Namen. Gib ihm einen. Falls du nächstes Jahr noch hier bist.',
      'fr': 'Il n\'a pas encore de nom. Donne-lui-en un. Si tu es encore là l\'année prochaine.',
      'id': 'Belum ada namanya. Kamu aja yang kasih nama. Kalau tahun depan kamu masih di sini.',
      'vi': 'Chưa có tên đâu. Cậu đặt đi. Nếu sang năm cậu vẫn còn ở đây.',
    },
    'sc_w7_3_title': {
