    'sc_w9_2_6': {
      'en': 'When I lose out, my face just shows it. Especially in front of you.',
      'ko': '손해 보면 그냥 손해 본 얼굴이 되거든. 너 앞에선 특히.',
      'ja': '損したら、そのまま損した顔になるから。特にあんたの前だと。',
      'zh': '吃亏的话表情就会藏不住。尤其是在你面前。',
