      'fr': '...On aurait dit qu\'on dessinait ensemble. J\'ai aimé ça.',
      'id': '...Rasanya kayak lagi gambar bareng. Aku suka.',
      'vi': '...Cảm giác như tụi mình đang cùng nhau vẽ tranh vậy. Tớ thích thế.',
