      'vi': 'Không biết. Chỉ là hai người thôi.',
    },
    'sc_w9_4_7': {
      'en': 'I won\'t erase it. Even something drawn badly is still a record.',
      'ko': '지우진 않을 거야. 잘 못 그린 것도 기록이니까.',
