      'vi': 'Tớ cũng vẽ một bức được không?',
    },
    'sc_w9_4_9': {
      'en': '...That\'s for later. Come to the club room. It\'s a game about avoiding triangles.',
      'ko': '…그건 나중에. 동아리실로 와. 삼각형 피하는 게임이야.',
      'ja': '…それは今度ね。部室に来て。三角形を避けるゲームだよ。',
      'zh': '……那个下次吧。到社团教室来。是躲避三角形的游戏。',
      'es': '...Eso para luego. Ven al club. Es un juego de evitar triángulos.',
      'pt': '...Isso fica pra depois. Vem pra sala do clube. É um jogo de evitar triângulos.',
