      'vi': '...Cái đó để sau đi. Đến phòng câu lạc bộ nhé. Là trò chơi tránh hình tam giác.',
    },
    'sc_w9_4_10': {
      'en': 'Triangle?',
      'ko': '삼각형?',
      'ja': '三角形?',
      'zh': '三角形?',
      'es': '¿Triángulos?',
      'pt': 'Triângulos?',
      'de': 'Dreiecke?',
      'fr': 'Des triangles ?',
      'id': 'Segitiga?',
      'vi': 'Tam giác á?',
    },
    'sc_w9_4_11': {
      'en': 'In that game, I draw the first line to start. That\'s the rule.',
      'ko': '그 게임은 내가 먼저 한 줄 긋고 시작해. 규칙이야.',
      'ja': 'そのゲームは私が最初の一本を引いて始めるの。ルールだから。',
      'zh': '那个游戏是我先画一条线开始的。是规则。',
      'es': 'En ese juego, yo trazo la primera línea para empezar. Es la regla.',
      'pt': 'Nesse jogo, eu traço a primeira linha pra começar. É a regra.',
