      'es': '...No. Es una excusa.',
      'pt': '...Não. É desculpa.',
      'de': '...Nein. Es ist eine Ausrede.',
      'fr': '...Non. C\'est une excuse.',
      'id': '...Bukan. Itu alasan aja.',
      'vi': '...Không. Là cái cớ thôi.',
