    'sc_w10_1_title': {
      'en': 'Key',
      'ko': '열쇠',
      'ja': '鍵',
      'zh': '钥匙',
      'es': 'Llave',
      'pt': 'Chave',
      'de': 'Schlüssel',
      'fr': 'Clé',
      'id': 'Kunci',
      'vi': 'Chìa khóa',
    },
    'sc_w10_1_1': {
      'en': 'I\'ve got the club room key. You can\'t run.',
      'ko': '동아리실 열쇠는 내가 갖고 있어. 도망 못 가.',
      'ja': '部室の鍵は私が持ってるから。逃げられないよ。',
