    },
    'sc_w10_1_5': {
      'en': 'In what way?',
      'ko': '어떤 점이?',
      'ja': 'どういうところが?',
      'zh': '哪里像了?',
      'es': '¿En qué sentido?',
      'pt': 'Em que sentido?',
      'de': 'Inwiefern?',
      'fr': 'En quoi?',
      'id': 'Mirip bagaimana?',
      'vi': 'Giống ở chỗ nào?',
    },
    'sc_w10_1_6': {
      'en': 'That avoiding it is exactly how you end up making one.',
      'ko': '피하다 보면 결국 만든다는 점.',
      'ja': '避けてるうちに結局作っちゃうところ。',
      'zh': '越躲最后越会造出一个。',
      'es': 'Que de tanto evitarlo, terminas creando uno.',
