    'sc_w11_2_1': {
      'en': 'Up to three lines per dot. That\'s the dot\'s life.',
      'ko': '점 하나에 선 세 개까지. 그게 그 점의 생명이야.',
      'ja': '点一つにつき線は三本まで。それがその点の命。',
      'zh': '一个点最多三条线。那就是那个点的生命。',
      'es': 'Hasta tres líneas por punto. Esa es la vida de ese punto.',
      'pt': 'Até três linhas por ponto. Essa é a vida do ponto.',
      'de': 'Bis zu drei Linien pro Punkt. Das ist sein Leben.',
      'fr': 'Trois lignes maximum par point. C\'est sa vie, à ce point-là.',
      'id': 'Maksimal tiga garis untuk satu titik. Itulah nyawa titik itu.',
      'vi': 'Mỗi chấm tối đa ba đường kẻ. Đó là sinh mệnh của chấm đó.',
    },
    'sc_w11_2_2': {
      'en': 'What if a new dot appears?',
      'ko': '새 점이 생기면?',
      'ja': '新しい点ができたら?',
      'zh': '要是出现新的点呢?',
      'es': '¿Y si aparece un punto nuevo?',
      'pt': 'E se aparecer um ponto novo?',
      'de': 'Und wenn ein neuer Punkt entsteht?',
      'fr': 'Et si un nouveau point apparaît?',
      'id': 'Kalau muncul titik baru?',
      'vi': 'Nếu có chấm mới xuất hiện thì sao?',
    },
    'sc_w11_2_3': {
      'en': 'It gains one more life.',
      'ko': '생명이 하나 늘어.',
      'ja': '命が一つ増える。',
      'zh': '生命就多一条。',
      'es': 'Gana una vida más.',
      'pt': 'Ganha mais uma vida.',
      'de': 'Dann kommt ein Leben dazu.',
      'fr': 'Il gagne une vie de plus.',
      'id': 'Nyawanya bertambah satu.',
      'vi': 'Nó có thêm một mạng.',
    },
    'sc_w11_2_4': {
      'en': '...Isn\'t that kind of human? Gaining something just from meeting someone.',
      'ko': '…그거 좀 사람 같지 않아? 만나면 하나 늘어나는 거.',
      'ja': '…それって、ちょっと人間っぽくない? 出会うと一つ増えるって。',
      'zh': '……那不是有点像人吗?一相遇就会多一样东西。',
      'es': '...¿No se parece un poco a las personas? Que al encontrarte con alguien ganes algo.',
      'pt': '...Não parece meio humano? Ganhar algo só de encontrar alguém.',
      'de': '...Ist das nicht irgendwie menschlich? Dass man durch eine Begegnung etwas dazugewinnt.',
      'fr': '...C\'est pas un peu comme les humains, ça? Gagner quelque chose rien qu\'en rencontrant quelqu\'un.',
      'id': '...Bukankah itu agak mirip manusia? Bertambah satu setiap kali bertemu.',
      'vi': '...Cái đó có hơi giống con người không? Gặp nhau là được thêm một thứ gì đó.',
    },
    'sc_w11_2_5': {
      'en': 'Human?',
      'ko': '사람?',
      'ja': '人間?',
      'zh': '人?',
      'es': '¿Personas?',
      'pt': 'Pessoas?',
      'de': 'Menschlich?',
      'fr': 'Les humains?',
      'id': 'Manusia?',
      'vi': 'Con người?',
    },
    'sc_w11_2_6': {
      'en': 'I\'m talking about plants. It\'s a greenhouse, after all.',
      'ko': '식물 얘기야. 온실이니까.',
      'ja': '植物の話だよ。温室だし。',
      'zh': '我说的是植物。毕竟是温室嘛。',
      'es': 'Hablo de las plantas. Estamos en un invernadero.',
      'pt': 'Estou falando de plantas. Afinal, é uma estufa.',
      'de': 'Ich rede von Pflanzen. Wir sind schließlich im Gewächshaus.',
      'fr': 'Je parle des plantes. On est dans une serre, après tout.',
