      'de': 'Sprössling',
      'fr': 'Pousse',
      'id': 'Kecambah',
      'vi': 'Mầm non',
    },
    'sc_w11_3_1': {
      'en': 'You\'re growing like a sprout, you know.',
      'ko': '새싹처럼 늘고 있어, 너.',
      'ja': '新芽みたいに伸びてるよ、あんた。',
      'zh': '你啊,像新芽一样在成长。',
      'es': 'Estás creciendo como un brote, ¿sabes?',
      'pt': 'Você está crescendo feito um broto, sabia?',
      'de': 'Du wächst wie ein Sprössling, weißt du das?',
      'fr': 'Tu grandis comme une pousse, tu sais.',
      'id': 'Kau ini tumbuh seperti kecambah, tahu.',
      'vi': 'Cậu đang lớn lên như một mầm cây đấy.',
    },
    'sc_w11_3_2': {
      'en': 'What about you?',
      'ko': '너는?',
      'ja': 'あんたは?',
      'zh': '那你呢?',
      'es': '¿Y tú?',
      'pt': 'E você?',
      'de': 'Und du?',
      'fr': 'Et toi?',
      'id': 'Kalau kau?',
      'vi': 'Còn cậu thì sao?',
    },
    'sc_w11_3_3': {
      'en': 'Me too, a little. Probably.',
      'ko': '나도 조금은. 아마.',
      'ja': '私も少しは。多分。',
      'zh': '我也一点点吧。大概。',
      'es': 'Yo también, un poco. Supongo.',
      'pt': 'Eu também, um pouco. Talvez.',
      'de': 'Ich wahrscheinlich auch. Ein bisschen.',
      'fr': 'Moi aussi, un peu. Sans doute.',
      'id': 'Aku juga sedikit. Mungkin.',
      'vi': 'Tớ cũng vậy, một chút. Chắc thế.',
    },
    'sc_w11_3_4': {
      'en': 'Sprouts grow where you can\'t see it. That\'s why you don\'t notice.',
      'ko': '새싹은 안 보이게 자라니까 모르는 거야.',
      'ja': '新芽は見えないところで育つから分かんないの。',
      'zh': '新芽是看不见的地方长大的,所以才不知道。',
      'es': 'Los brotes crecen donde no se ve, por eso no te das cuenta.',
      'pt': 'Brotos crescem onde não dá pra ver, por isso você não percebe.',
      'de': 'Sprösslinge wachsen unsichtbar, deshalb merkt man\'s nicht.',
      'fr': 'Les pousses grandissent là où on les voit pas, c\'est pour ça qu\'on remarque rien.',
      'id': 'Kecambah tumbuh tanpa terlihat, makanya kau tidak sadar.',
      'vi': 'Mầm cây lớn lên ở chỗ không thấy được, nên mới không biết đấy thôi.',
    },
    'sc_w11_3_5': {
      'en': 'I can see it, though.',
      'ko': '보이는데.',
      'ja': '見えるけど。',
      'zh': '我能看见啊。',
      'es': 'Pero se te ve.',
      'pt': 'Mas dá pra ver.',
      'de': 'Aber ich seh\'s doch.',
      'fr': 'Mais je le vois, moi.',
      'id': 'Padahal aku bisa melihatnya.',
      'vi': 'Nhưng tớ thấy được mà.',
    },
    'sc_w11_3_6': {
      'en': '...Then don\'t look.',
      'ko': '…그럼 보지 마.',
      'ja': '…じゃあ見ないで。',
      'zh': '……那就别看。',
      'es': '...Entonces no mires.',
      'pt': '...Então não olhe.',
      'de': '...Dann guck nicht hin.',
      'fr': '...Alors regarde pas.',
      'id': '...Kalau begitu jangan lihat.',
      'vi': '...Vậy thì đừng nhìn.',
