    'sc_w11_4_title': {
      'en': 'The Sprout in the Greenhouse',
      'ko': '온실의 새싹',
      'ja': '温室の新芽',
      'zh': '温室的新芽',
      'es': 'El brote del invernadero',
      'pt': 'O broto da estufa',
      'de': 'Der Sprössling im Gewächshaus',
      'fr': 'La pousse de la serre',
      'id': 'Kecambah di Rumah Kaca',
      'vi': 'Mầm non trong nhà kính',
    },
    'sc_w11_4_1': {
      'en': 'Sprouts is done. The greenhouse sprouts are fully grown too.',
      'ko': '스프라우트 끝. 온실 새싹도 다 자랐어.',
      'ja': 'スプラウト終わり。温室の新芽も全部育った。',
      'zh': 'Sprouts结束了。温室的新芽也都长大了。',
      'es': 'Se acabó Sprouts. Los brotes del invernadero también terminaron de crecer.',
      'pt': 'Acabou o Sprouts. Os brotos da estufa também já cresceram todos.',
      'de': 'Sprouts ist vorbei. Die Sprösslinge im Gewächshaus sind auch fertig gewachsen.',
      'fr': 'Sprouts, c\'est fini. Les pousses de la serre ont fini de grandir aussi.',
      'id': 'Sprouts selesai. Kecambah di rumah kaca juga sudah tumbuh besar semua.',
      'vi': 'Sprouts xong rồi. Mầm cây trong nhà kính cũng đã lớn hết cả.',
    },
    'sc_w11_4_2': {
      'en': 'I planted them the day you first came here. The day of the four candies.',
      'ko': '네가 처음 온 날 심은 거야. 사탕 네 개 하던 날.',
      'ja': 'あんたが初めて来た日に植えたの。飴四個の日。',
      'zh': '是你第一次来的那天种下的。吃四颗糖那天。',
      'es': 'Los planté el día que viniste por primera vez. El día de los cuatro caramelos.',
      'pt': 'Plantei no dia em que você veio pela primeira vez. O dia dos quatro doces.',
      'de': 'Ich hab sie an dem Tag gepflanzt, an dem du zum ersten Mal herkamst. Der Tag mit den vier Bonbons.',
      'fr': 'Je les ai plantées le jour où t\'es venu pour la première fois. Le jour des quatre bonbons.',
      'id': 'Kutanam di hari pertama kau datang ke sini. Hari yang ada empat permennya itu.',
      'vi': 'Tớ trồng vào ngày cậu đến đây lần đầu. Ngày có bốn viên kẹo ấy.',
    },
    'sc_w11_4_3': {
      'en': 'That day?',
      'ko': '그날?',
      'ja': 'あの日?',
      'zh': '那天?',
      'es': '¿Ese día?',
      'pt': 'Naquele dia?',
      'de': 'An dem Tag?',
      'fr': 'Ce jour-là?',
      'id': 'Hari itu?',
      'vi': 'Ngày đó à?',
    },
    'sc_w11_4_4': {
      'en': 'I never told you. I was afraid if I did, you wouldn\'t come back.',
      'ko': '말 안 했지. 말하면 네가 안 올까 봐.',
      'ja': '言わなかったよ。言ったらあんたが来なくなりそうで。',
      'zh': '我没说过吧。怕说了你就不来了。',
      'es': 'Nunca te lo dije. Tenía miedo de que si te lo decía, no volvieras.',
      'pt': 'Nunca te contei. Tinha medo que, se contasse, você não voltasse mais.',
      'de': 'Ich hab\'s dir nie gesagt. Ich hatte Angst, du kämst dann nicht mehr.',
      'fr': 'Je te l\'ai jamais dit. J\'avais peur que si je le disais, tu reviennes plus.',
      'id': 'Aku tidak pernah bilang. Takut kalau kubilang, kau jadi tidak datang lagi.',
      'vi': 'Tớ chưa từng nói. Sợ nói ra thì cậu sẽ không đến nữa.',
    },
    'sc_w11_4_5': {
      'en': 'Why wouldn\'t I come?',
      'ko': '왜 안 와?',
      'ja': 'なんで来なくなるの?',
      'zh': '为什么会不来?',
      'es': '¿Por qué no iba a volver?',
      'pt': 'Por que eu não voltaria?',
      'de': 'Warum sollte ich nicht mehr kommen?',
      'fr': 'Pourquoi je serais plus revenu?',
      'id': 'Kenapa memangnya aku jadi tidak datang?',
      'vi': 'Sao lại không đến?',
    },
    'sc_w11_4_6': {
      'en': '...Because it\'d feel like too much pressure. Now that they\'re fully grown, I guess it\'s okay to say.',
      'ko': '…부담스러워서. 다 자랐으니까 이제 말해도 되겠지.',
      'ja': '…重く感じそうで。もう全部育ったから、言ってもいいよね。',
      'zh': '……怕你觉得有负担。都长大了,现在说应该没关系了吧。',
      'es': '...Porque te agobiaría. Ya que terminaron de crecer, supongo que ya puedo decírtelo.',
      'pt': '...Porque ia pesar pra você. Já que cresceram todos, acho que agora posso contar.',
      'de': '...Weil es dich vielleicht belastet hätte. Jetzt, wo sie fertig gewachsen sind, kann ich\'s wohl sagen.',
      'fr': '...Parce que ça t\'aurait mis la pression. Maintenant qu\'elles ont fini de pousser, je peux bien te le dire.',
      'id': '...Takut terasa membebani. Karena sudah tumbuh besar semua, sekarang boleh kuberi tahu, kan.',
      'vi': '...Sợ khiến cậu thấy áp lực. Giờ chúng lớn hết rồi, chắc nói ra cũng được.',
    },
    'sc_w11_4_7': {
      'en': 'Last stop is the board game club. Hex. A game with no draws.',
      'ko': '마지막은 보드게임부야. 헥스. 비기는 판이 없는 게임.',
      'ja': '最後はボードゲーム部。ヘックス。引き分けのないゲーム。',
      'zh': '最后是棋牌社。Hex。一个不会平局的游戏。',
      'es': 'Lo último es el club de juegos de mesa. Hex. Un juego sin empates.',
      'pt': 'O último é o clube de jogos de tabuleiro. Hex. Um jogo sem empates.',
      'de': 'Als Letztes kommt der Brettspielclub. Hex. Ein Spiel ohne Unentschieden.',
      'fr': 'La dernière étape, c\'est le club de jeux de société. Hex. Un jeu sans match nul.',
      'id': 'Terakhir klub board game. Hex. Permainan yang tidak pernah seri.',
      'vi': 'Cuối cùng là câu lạc bộ board game. Hex. Trò chơi không có hòa.',
    },
    'sc_w11_4_8': {
      'en': 'No draws at all?',
      'ko': '비기는 게 없어?',
      'ja': '引き分けがないの?',
      'zh': '不会平局吗?',
      'es': '¿No hay empates?',
      'pt': 'Não tem empate mesmo?',
      'de': 'Gibt\'s wirklich kein Unentschieden?',
      'fr': 'Y a vraiment jamais match nul?',
      'id': 'Tidak pernah seri?',
      'vi': 'Không bao giờ hòa à?',
    },
    'sc_w11_4_9': {
      'en': 'Right. Because blocking is the same as connecting.',
      'ko': '응. 막는 게 곧 잇는 거라서.',
      'ja': 'うん。塞ぐことがそのまま繋げることだから。',
      'zh': '嗯。因为阻挡本身就是连接。',
      'es': 'Sí. Porque bloquear es lo mismo que conectar.',
      'pt': 'É. Porque bloquear é a mesma coisa que conectar.',
      'de': 'Ja. Weil Blockieren gleichzeitig Verbinden bedeutet.',
