    },
    'sc_w11_4_10': {
      'en': 'Us too?',
      'ko': '우리도?',
      'ja': '私たちも?',
      'zh': '我们也是吗?',
      'es': '¿Nosotros también?',
      'pt': 'A gente também?',
      'de': 'Wir auch?',
      'fr': 'Nous aussi?',
      'id': 'Kita juga begitu?',
      'vi': 'Chúng ta cũng vậy sao?',
    },
    'sc_w11_4_11': {
      'en': 'Yeah, we\'re the same. There\'s no draw for us either.',
      'ko': '우리도 그렇잖아. 비기는 건 없어.',
      'ja': '私たちもそうじゃん。引き分けなんてない。',
      'zh': '我们也一样吧。没有平局这回事。',
