    },
    'sc_w12_1_title': {
      'en': 'New Member',
      'ko': '신입',
      'ja': '新入り',
      'zh': '新人',
      'es': 'Novato',
      'pt': 'Novato',
      'de': 'Neuling',
      'fr': 'Nouvelle recrue',
      'id': 'Anggota Baru',
      'vi': 'Thành viên mới',
    },
    'sc_w12_1_1': {
      'en': 'Welcome to the board game club, newbie. There\'s no leaving now.',
      'ko': '보드게임부 신입 환영. 이제 넌 못 나가.',
      'ja': 'ボードゲーム部新入り歓迎。もう抜けられないから。',
      'zh': '欢迎加入棋牌社,新人。现在你可退不了了。',
      'es': 'Bienvenido al club de juegos de mesa, novato. Ya no puedes salir.',
      'pt': 'Bem-vindo ao clube de jogos de tabuleiro, novato. Agora você não sai mais.',
      'de': 'Willkommen im Brettspielclub, Neuling. Jetzt kommst du nicht mehr raus.',
      'fr': 'Bienvenue au club de jeux de société, petit nouveau. Maintenant tu peux plus sortir.',
