    'sc_w12_1_2': {
      'en': 'I wasn\'t planning to leave.',
      'ko': '나갈 생각 없어.',
      'ja': '抜けるつもりないけど。',
      'zh': '我没打算退。',
      'es': 'No pensaba salir.',
      'pt': 'Eu não pretendia sair.',
      'de': 'Ich hatte nicht vor, zu gehen.',
      'fr': 'J\'avais pas l\'intention de partir.',
      'id': 'Aku tidak berniat keluar.',
      'vi': 'Tớ đâu định rút.',
    },
    'sc_w12_1_3': {
      'en': 'Still can\'t leave. It\'s the rule.',
      'ko': '그래도 못 나가. 규칙이야.',
      'ja': 'それでも抜けられない。規則だから。',
      'zh': '就算这样也退不了。这是规矩。',
      'es': 'Aun así, no puedes salir. Es la regla.',
      'pt': 'Mesmo assim, você não sai. É a regra.',
      'de': 'Trotzdem geht\'s nicht. Das ist die Regel.',
      'fr': 'Quand même, tu peux pas. C\'est la règle.',
      'id': 'Tetap saja tidak bisa keluar. Itu aturannya.',
      'vi': 'Vẫn không rút được. Đó là quy tắc.',
    },
    'sc_w12_1_4': {
      'en': 'Watching you connect left to right gave me chills.',
      'ko': '좌우 연결하는 거 보고 소름 돋았어.',
      'ja': '左右を繋げるの見て鳥肌立った。',
      'zh': '看你把左右连起来,我起鸡皮疙瘩了。',
      'es': 'Ver cómo conectaste de izquierda a derecha me puso la piel de gallina.',
      'pt': 'Ver você conectar da esquerda pra direita me deu arrepios.',
      'de': 'Als ich gesehen hab, wie du links und rechts verbunden hast, hatte ich Gänsehaut.',
      'fr': 'Te voir relier la gauche à la droite, ça m\'a donné des frissons.',
      'id': 'Melihat kau menyambungkan kiri dan kanan tadi bikin aku merinding.',
      'vi': 'Nhìn cậu nối trái phải xong tớ nổi da gà luôn.',
    },
    'sc_w12_1_5': {
      'en': 'The bad kind?',
      'ko': '나쁜 쪽?',
      'ja': '悪い方の?',
      'zh': '是坏的那种吗?',
      'es': '¿De las malas?',
      'pt': 'Do tipo ruim?',
      'de': 'Die schlechte Art?',
      'fr': 'Le mauvais genre?',
      'id': 'Merinding buruk?',
      'vi': 'Kiểu tệ hả?',
    },
    'sc_w12_1_6': {
      'en': 'The good kind. There is such a thing, you know.',
      'ko': '좋은 쪽. 그런 것도 있어.',
      'ja': 'いい方。そういうのもあるの。',
      'zh': '是好的那种。还有这种呢。',
      'es': 'De las buenas. Existen esas también.',
      'pt': 'Do tipo bom. Também existe esse tipo, sabia.',
      'de': 'Die gute Art. Sowas gibt\'s auch.',
      'fr': 'Le bon genre. Ça existe aussi, tu sais.',
      'id': 'Merinding baik. Ada juga jenis itu, tahu.',
      'vi': 'Kiểu tốt. Kiểu đó cũng có đấy.',
