    'sc_w12_2_title': {
      'en': 'Bridge',
      'ko': '다리',
      'ja': '橋',
      'zh': '桥',
      'es': 'Puente',
      'pt': 'Ponte',
      'de': 'Brücke',
      'fr': 'Pont',
      'id': 'Jembatan',
      'vi': 'Cây cầu',
    },
    'sc_w12_2_1': {
      'en': 'In Hex, even if you\'re blocked, there\'s a way around to connect. It\'s called a bridge.',
      'ko': '헥스는 막혀도 돌아서 이어지는 길이 있어. 다리라고 해.',
      'ja': 'ヘックスは塞がれても迂回して繋がる道があるの。橋って呼ぶんだ。',
      'zh': 'Hex就算被挡住,也有绕路连接的办法。这叫桥。',
      'es': 'En Hex, aunque te bloqueen, hay un camino para rodear y conectar. Se llama puente.',
      'pt': 'No Hex, mesmo bloqueado, há um jeito de contornar e conectar. Chama-se ponte.',
      'de': 'Bei Hex gibt\'s, auch wenn man blockiert ist, einen Weg drumherum, der verbindet. Man nennt das Brücke.',
      'fr': 'Dans Hex, même bloqué, il y a un chemin détourné pour relier. On appelle ça un pont.',
      'id': 'Di Hex, meski terhalang, ada jalan memutar untuk tetap tersambung. Itu disebut jembatan.',
      'vi': 'Trong Hex, dù bị chặn vẫn có đường vòng để nối lại. Gọi là cây cầu.',
    },
    'sc_w12_2_2': {
      'en': 'What if you block it?',
      'ko': '막으면?',
      'ja': '塞いだら?',
      'zh': '那要是挡住了呢?',
      'es': '¿Y si lo bloqueas?',
      'pt': 'E se bloquear?',
      'de': 'Und wenn man\'s blockiert?',
      'fr': 'Et si on la bloque?',
      'id': 'Kalau dihalangi?',
      'vi': 'Nếu chặn thì sao?',
    },
    'sc_w12_2_3': {
      'en': 'It connects the other way instead. You can\'t cut it off.',
      'ko': '다른 쪽으로 잇지. 못 끊어.',
      'ja': '反対側で繋げるだけ。切れないよ。',
      'zh': '那就从另一边接上。切不断的。',
      'es': 'Se conecta por el otro lado, entonces. No se puede cortar.',
      'pt': 'Conecta pelo outro lado. Não dá pra cortar.',
      'de': 'Dann verbindet sie sich eben von der anderen Seite. Man kann sie nicht durchtrennen.',
      'fr': 'Ça se relie par l\'autre côté. On peut pas la couper.',
      'id': 'Ya tersambung lewat sisi lain. Tidak bisa diputus.',
      'vi': 'Thì nối bằng phía bên kia. Không cắt đứt được đâu.',
    },
    'sc_w12_2_4': {
      'en': '...Don\'t you think we\'re at least that solid by now? We\'ve played over a hundred rounds.',
      'ko': '…나랑 너도 그 정도는 되지 않았을까. 백 판 넘게 뒀는데.',
      'ja': '…私とあんたも、それくらいにはなってるんじゃない? 百戦以上したんだから。',
      'zh': '……我和你,是不是也到那种程度了?都下了一百多局了。',
      'es': '...¿No crees que tú y yo ya hemos llegado a eso? Ya jugamos más de cien partidas.',
      'pt': '...Você não acha que a gente já chegou nesse ponto? A gente já jogou mais de cem partidas.',
      'de': '...Sind du und ich nicht auch schon so weit? Wir haben über hundert Runden gespielt.',
      'fr': '...Toi et moi, on en est pas déjà là? On a joué plus de cent parties, quand même.',
      'id': '...Kau dan aku, bukankah sudah sampai tahap itu? Sudah main lebih dari seratus ronde.',
      'vi': '...Tớ với cậu chắc cũng đến mức đó rồi nhỉ. Chơi hơn trăm ván rồi còn gì.',
    },
    'sc_w12_2_5': {
      'en': 'A bridge?',
      'ko': '다리?',
      'ja': '橋?',
      'zh': '桥?',
      'es': '¿Un puente?',
      'pt': 'Uma ponte?',
      'de': 'Eine Brücke?',
      'fr': 'Un pont?',
      'id': 'Jembatan?',
      'vi': 'Cây cầu?',
    },
    'sc_w12_2_6': {
      'en': 'Something that connects the other way even when blocked. That kind of thing.',
      'ko': '막아도 다른 쪽으로 이어지는 거. 그런 거.',
      'ja': '塞がれても反対側で繋がるやつ。そういうやつ。',
      'zh': '就算被挡也能从另一边接上的东西。就是那种。',
      'es': 'Algo que se conecta por otro lado aunque lo bloqueen. Ese tipo de cosa.',
      'pt': 'Uma coisa que conecta pelo outro lado mesmo bloqueada. Esse tipo de coisa.',
      'de': 'Etwas, das sich auch blockiert noch von der anderen Seite verbindet. So etwas.',
      'fr': 'Un truc qui se relie par un autre côté même quand on le bloque. Ce genre de chose.',
      'id': 'Sesuatu yang tetap tersambung meski dihalangi. Semacam itu.',
      'vi': 'Thứ mà dù bị chặn vẫn nối được bằng phía khác. Kiểu như vậy đấy.',
    },
    'sc_w12_3_title': {
      'en': 'A Hundred Times',
      'ko': '백 번',
      'ja': '百回',
      'zh': '一百次',
      'es': 'Cien veces',
      'pt': 'Cem vezes',
      'de': 'Hundert Mal',
      'fr': 'Cent fois',
      'id': 'Seratus Kali',
      'vi': 'Trăm lần',
    },
    'sc_w12_3_1': {
      'en': 'Next time I\'ll win. For real.',
      'ko': '다음엔 내가 이겨. 진짜로.',
      'ja': '次は私が勝つ。本当に。',
      'zh': '下次我一定赢。真的。',
      'es': 'La próxima gano yo. En serio.',
      'pt': 'Da próxima eu ganho. De verdade.',
      'de': 'Nächstes Mal gewinne ich. Wirklich.',
      'fr': 'La prochaine fois, je gagne. Pour de vrai.',
      'id': 'Lain kali aku yang menang. Sungguhan.',
      'vi': 'Lần sau tớ sẽ thắng. Thật đấy.',
    },
    'sc_w12_3_2': {
      'en': 'How many times have you said that now?',
      'ko': '그 말 몇 번째야?',
      'ja': 'それ何回目?',
      'zh': '这句话你说第几次了?',
      'es': '¿Cuántas veces llevas diciendo eso?',
      'pt': 'Quantas vezes você já disse isso?',
      'de': 'Wie oft hast du das jetzt schon gesagt?',
      'fr': 'Ça fait combien de fois que tu dis ça?',
      'id': 'Sudah berapa kali kau bilang begitu?',
      'vi': 'Cậu nói câu đó bao nhiêu lần rồi?',
    },
    'sc_w12_3_3': {
      'en': '...About a hundred times.',
      'ko': '…백 번쯤.',
      'ja': '…百回くらい。',
      'zh': '……大概一百次吧。',
      'es': '...Como unas cien veces.',
      'pt': '...Umas cem vezes.',
      'de': '...So ungefähr hundert Mal.',
      'fr': '...Une centaine de fois, à peu près.',
      'id': '...Sekitar seratus kali.',
      'vi': '...Khoảng trăm lần rồi.',
    },
    'sc_w12_3_4': {
      'en': 'The hundred-and-first time will be different.',
      'ko': '백한 번째는 다를 거야.',
      'ja': '百一回目は違うから。',
      'zh': '第一百零一次会不一样的。',
      'es': 'La vez ciento uno será distinta.',
      'pt': 'A centésima primeira vez vai ser diferente.',
      'de': 'Beim hunderteinsten Mal wird\'s anders sein.',
      'fr': 'La cent-unième fois, ce sera différent.',
      'id': 'Yang keseratus satu akan berbeda.',
      'vi': 'Lần thứ một trăm lẻ một sẽ khác.',
    },
    'sc_w12_3_5': {
      'en': 'Why?',
      'ko': '왜?',
      'ja': 'なんで?',
      'zh': '为什么?',
      'es': '¿Por qué?',
      'pt': 'Por quê?',
      'de': 'Warum?',
      'fr': 'Pourquoi?',
      'id': 'Kenapa?',
      'vi': 'Tại sao?',
    },
    'sc_w12_3_6': {
      'en': 'Dunno. I just decided it\'ll be that way.',
      'ko': '몰라. 그냥 그렇게 정했어.',
      'ja': '知らない。ただそう決めたの。',
      'zh': '不知道。就是这么决定的。',
      'es': 'No sé. Simplemente lo decidí así.',
      'pt': 'Não sei. Só decidi que vai ser assim.',
      'de': 'Weiß nicht. Ich hab\'s einfach so beschlossen.',
      'fr': 'Sais pas. J\'ai juste décidé que ce serait comme ça.',
      'id': 'Tidak tahu. Pokoknya sudah kuputuskan begitu.',
      'vi': 'Không biết. Chỉ là tớ quyết định thế thôi.',
    },
    'sc_w12_4_title': {
      'en': 'The End of After School, and Then',
      'ko': '방과후의 끝, 그리고',
      'ja': '放課後の終わり、そして',
      'zh': '放学后的终点,以及',
      'es': 'El final de después de clases, y luego',
      'pt': 'O fim do pós-aula, e então',
      'de': 'Das Ende des Nachmittags, und dann',
      'fr': 'La fin de l\'après-cours, et ensuite',
      'id': 'Akhir Sepulang Sekolah, dan Kemudian',
      'vi': 'Kết thúc giờ tan học, và rồi',
    },
    'sc_w12_4_1': {
      'en': 'Two hundred forty rounds. You won every single one.',
      'ko': '이백사십 판. 전부 네가 이겼어.',
      'ja': '二百四十戦。全部あんたが勝った。',
      'zh': '二百四十局。全都是你赢的。',
      'es': 'Doscientas cuarenta partidas. Las ganaste todas.',
      'pt': 'Duzentas e quarenta partidas. Você ganhou todas.',
      'de': 'Zweihundertvierzig Runden. Du hast jede einzelne gewonnen.',
      'fr': 'Deux cent quarante parties. Tu les as toutes gagnées.',
      'id': 'Dua ratus empat puluh ronde. Semuanya kau yang menang.',
      'vi': 'Hai trăm bốn mươi ván. Cậu thắng hết tất cả.',
    },
    'sc_w12_4_2': {
      'en': 'I\'ll hand over the board game club president position to you. For real this time.',
      'ko': '보드게임부 부장 자리, 너한테 물려줄게. 이번엔 진짜.',
      'ja': 'ボードゲーム部の部長の座、あんたに譲るよ。今度こそ本当に。',
      'zh': '棋牌社社长的位子,让给你。这次是真的。',
      'es': 'Te cedo el puesto de presidente del club de juegos de mesa. Esta vez va en serio.',
      'pt': 'Vou passar o cargo de presidente do clube de jogos de tabuleiro pra você. Dessa vez é de verdade.',
      'de': 'Den Posten als Präsident des Brettspielclubs übergebe ich dir. Diesmal wirklich.',
      'fr': 'Je te cède le poste de président du club de jeux de société. Cette fois, c\'est du sérieux.',
      'id': 'Posisi ketua klub board game, kuserahkan padamu. Kali ini sungguhan.',
      'vi': 'Vị trí chủ tịch câu lạc bộ board game, tớ nhường lại cho cậu. Lần này là thật đấy.',
    },
    'sc_w12_4_3': {
      'en': 'What\'s the catch?',
      'ko': '조건은?',
      'ja': '条件は?',
      'zh': '条件是?',
      'es': '¿Y la condición?',
      'pt': 'E a condição?',
      'de': 'Und die Bedingung?',
      'fr': 'Et la condition?',
      'id': 'Syaratnya?',
      'vi': 'Điều kiện là gì?',
    },
    'sc_w12_4_4': {
      'en': 'There is one. I stay on as a regular member.',
      'ko': '있어. 내가 부원으로 남는 거.',
      'ja': 'あるよ。私が部員として残ること。',
      'zh': '有。我留下来当社员。',
      'es': 'Sí hay. Que yo me quede como miembro normal.',
      'pt': 'Tem sim. Eu ficar como membro comum.',
      'de': 'Ja, eine. Dass ich als Mitglied bleibe.',
      'fr': 'Oui, il y en a une. Que je reste membre.',
      'id': 'Ada. Aku tetap jadi anggota biasa.',
      'vi': 'Có chứ. Là tớ vẫn ở lại làm thành viên.',
    },
    'sc_w12_4_5': {
      'en': 'Of course.',
      'ko': '당연하지.',
      'ja': '当然だよ。',
      'zh': '那是当然。',
      'es': 'Por supuesto.',
      'pt': 'Claro que sim.',
      'de': 'Natürlich.',
      'fr': 'Évidemment.',
      'id': 'Tentu saja.',
      'vi': 'Đương nhiên rồi.',
    },
    'sc_w12_4_6': {
      'en': 'Because if there\'s no one left to beat, I\'ll end up playing alone again.',
      'ko': '이길 상대가 없으면 나는 또 혼자 두게 되니까.',
      'ja': '勝つ相手がいなくなったら、また一人で打つことになるから。',
      'zh': '没了能赢的对手,我又要一个人下棋了。',
      'es': 'Porque si no tengo a nadie a quien ganarle, volveré a jugar sola.',
      'pt': 'Porque se não tiver ninguém pra vencer, eu volto a jogar sozinha.',
      'de': 'Weil ich sonst, ohne jemanden zum Gewinnen, wieder alleine spiele.',
      'fr': 'Parce que si j\'ai plus personne à battre, je me retrouve à jouer toute seule.',
      'id': 'Karena kalau tidak ada lawan yang bisa kukalahkan, aku jadi main sendirian lagi.',
      'vi': 'Vì nếu không còn ai để thắng, tớ lại phải chơi một mình mất.',
    },
    'sc_w12_4_7': {
      'en': 'What I meant to say back at the greenhouse — I\'ll say it now.',
      'ko': '온실에서 하려던 말, 지금 할게.',
      'ja': '温室で言おうとしてたこと、今言うね。',
      'zh': '在温室想说的话,现在说。',
      'es': 'Lo que quería decirte en el invernadero, te lo digo ahora.',
      'pt': 'O que eu ia te dizer na estufa, vou dizer agora.',
      'de': 'Was ich dir im Gewächshaus sagen wollte, sag ich dir jetzt.',
      'fr': 'Ce que je voulais te dire à la serre, je te le dis maintenant.',
      'id': 'Yang ingin kukatakan di rumah kaca waktu itu, akan kukatakan sekarang.',
      'vi': 'Điều tớ định nói ở nhà kính, giờ tớ sẽ nói.',
    },
    'sc_w12_4_8': {
      'en': 'Okay.',
      'ko': '응.',
      'ja': 'うん。',
      'zh': '嗯。',
      'es': 'Vale.',
      'pt': 'Tá.',
      'de': 'Okay.',
      'fr': 'D\'accord.',
      'id': 'Ya.',
      'vi': 'Ừ.',
    },
    'sc_w12_4_9': {
      'en': 'There\'s no draw for us. So come again tomorrow. After school.',
      'ko': '우리는 비기는 게 없어. 그러니까 내일도 와. 방과후에.',
      'ja': '私たちに引き分けはない。だから明日も来て。放課後に。',
      'zh': '我们没有平局。所以明天也要来。放学后。',
      'es': 'Para nosotros no hay empate. Así que ven mañana también. Después de clases.',
      'pt': 'Pra gente não existe empate. Então venha amanhã também. Depois da aula.',
      'de': 'Für uns gibt es kein Unentschieden. Also komm auch morgen. Nach der Schule.',
      'fr': 'Pour nous, y a pas de match nul. Alors reviens demain aussi. Après les cours.',
      'id': 'Kita tidak pernah seri. Jadi besok datang lagi. Sepulang sekolah.',
      'vi': 'Chúng ta không có hòa. Nên mai cũng đến nhé. Sau giờ tan học.',
    },
    'sc_w12_4_10': {
      'en': 'I\'ll be there.',
      'ko': '갈게.',
      'ja': '行く。',
      'zh': '我会去的。',
      'es': 'Ahí estaré.',
      'pt': 'Eu vou.',
      'de': 'Ich komme.',
      'fr': 'J\'y serai.',
      'id': 'Aku akan datang.',
      'vi': 'Tớ sẽ đến.',
    },
    'sc_w12_4_11': {
      'en': 'I\'ll bring candy. Just like the first time.',
      'ko': '사탕 가져갈게. 처음처럼.',
      'ja': '飴持ってくね。最初みたいに。',
      'zh': '我会带糖来的。像第一次那样。',
      'es': 'Traeré caramelos. Como la primera vez.',
      'pt': 'Vou levar doces. Igual da primeira vez.',
      'de': 'Ich bring Bonbons mit. So wie beim ersten Mal.',
      'fr': 'J\'apporterai des bonbons. Comme la première fois.',
      'id': 'Akan kubawakan permen. Seperti waktu pertama kali.',
      'vi': 'Tớ sẽ mang kẹo theo. Như lần đầu tiên ấy.',
    },
    'sc_w12_4_12': {
      'en': '...No, actually — a little more than the first time.',
      'ko': '…아니, 처음보다 조금 더.',
      'ja': '…ううん、最初よりちょっと多めに。',
      'zh': '……不,比第一次多一点。',
      'es': '...No, un poco más que la primera vez.',
      'pt': '...Não, um pouco mais que da primeira vez.',
      'de': '...Nein, ein bisschen mehr als beim ersten Mal.',
      'fr': '...Non, un peu plus que la première fois.',
      'id': '...Tidak, sedikit lebih banyak dari yang pertama.',
      'vi': '...Không, nhiều hơn lần đầu một chút.',
    },
    'rx_w1_1': {
      'en': 'Ex: 10 candies, take 1-2 at a time. I take 2 → Yerin takes 1 → … Whoever takes the last one wins.',
      'ko': '예: 사탕 10개, 한 번에 1~2개. 내가 2개 → 예린이 1개 → … 마지막 하나를 집는 사람이 이겨.',
      'ja': '例: 飴10個、一度に1〜2個。私が2個 → イェリンが1個 → … 最後の一つを取った人が勝ち。',
      'zh': '例:糖果10个,每次拿1~2个。我拿2个 → 艺琳拿1个 → …拿到最后一个的人获胜。',
      'es': 'Ej: 10 caramelos, 1-2 por turno. Yo tomo 2 → Yerin toma 1 → … Quien tome el último gana.',
      'pt': 'Ex: 10 doces, 1-2 por vez. Eu pego 2 → Yerin pega 1 → … Quem pegar o último vence.',
      'de': 'Bsp.: 10 Bonbons, 1-2 pro Zug. Ich nehme 2 → Yerin nimmt 1 → … Wer das letzte nimmt, gewinnt.',
      'fr': 'Ex : 10 bonbons, 1 à 2 par tour. Je prends 2 → Yerin prend 1 → … Qui prend le dernier gagne.',
      'id': 'Cth: 10 permen, ambil 1-2 per giliran. Aku ambil 2 → Yerin ambil 1 → … Siapa yang ambil yang terakhir menang.',
      'vi': 'VD: 10 viên kẹo, mỗi lượt lấy 1-2 viên. Mình lấy 2 → Yerin lấy 1 → … Ai lấy viên cuối cùng thắng.',
    },
    'rx_w1_2': {
      'en': 'Anywhere from 1 up to the max. 0 isn\'t allowed.',
      'ko': '1개도 되고 최대 개수까지 아무거나. 0개는 안 돼.',
      'ja': '1個でも最大数までなら何でもいい。0個はダメ。',
      'zh': '1个也行,最多到上限都可以,但0个不行。',
      'es': 'Puedes tomar desde 1 hasta el máximo. 0 no vale.',
      'pt': 'Pode ser 1 até o máximo. 0 não vale.',
      'de': 'Von 1 bis zum Maximum ist alles erlaubt. 0 geht nicht.',
      'fr': 'De 1 jusqu\'au maximum, comme tu veux. 0 n\'est pas permis.',
      'id': 'Boleh 1 sampai jumlah maksimum, terserah. 0 tidak boleh.',
      'vi': 'Lấy từ 1 đến tối đa đều được. Không được lấy 0.',
    },
    'rx_w2_1': {
      'en': 'Two rows. Pick one row per turn, and take anywhere from 1 up to all of it.',
      'ko': '줄이 두 개. 한 번에 한 줄만 고르고, 그 줄에서는 1개부터 전부까지 마음대로.',
      'ja': '列が二つ。一度に一つの列だけ選んで、その列では1個から全部まで自由に。',
      'zh': '有两行。每次只能选一行,那一行里从1个到全部随便拿。',
      'es': 'Dos filas. Elige una fila por turno y toma desde 1 hasta todo lo que quieras de ella.',
