    'rx_w11_2': {
      'en': 'Each dot can have up to 3 lines. Lines can\'t cross each other. Whoever can\'t connect anymore loses.',
      'ko': '한 점에는 선이 3개까지. 선은 서로 겹칠 수 없어. 더 이을 수 없는 사람이 져.',
      'ja': '一つの点には線が3本まで。線同士は重なれない。もうつなげない人が負け。',
      'zh': '一个点最多能连3条线。线与线不能交叉。无法再连线的人就输了。',
      'es': 'Cada punto puede tener hasta 3 líneas. Las líneas no pueden cruzarse. Quien no pueda conectar más pierde.',
