    'rx_w12_1': {
      'en': 'Take turns claiming hexagon cells. I win by connecting left↔right; Yerin wins by connecting top↔bottom.',
      'ko': '육각형 칸을 번갈아 차지해. 나는 왼쪽↔오른쪽, 예린은 위↔아래를 이으면 이겨.',
      'ja': '六角形のマスを交互に取る。私は左↔右、イェリンは上↔下をつなげば勝ち。',
      'zh': '轮流占据六边形格子。我连接左↔右就赢,艺琳连接上↔下就赢。',
